KG42.register("clusters-0f23cbd86ef1daadf7a43817",{"id":"05-double_auction::v142-d-CL006","paper":"05-double_auction","label":"Marginal pricing and a common transaction rate in uniform k-DA","record":{"cluster_id":"v142-d-CL006","label":"Marginal pricing and a common transaction rate in uniform k-DA","market_meaning":"After natural ordering and the maximum break-even position have been determined, the buyer and seller quotations at that position form a uniform price, which is used for trade execution and bilateral payment and receipt rates for all winning participants.","mechanism_ids":["v141-a-M02"],"market_types":["LEM"],"process_stages":["pricing","activation","settlement"],"scope_disposition":"unresolved","scope_explanation":"All three chains belong to M02 and share price inputs from the same marginal position, but the interval imposed on k by R014 is not explicitly stated in the cited M02 evidence. The parameter domain and case-study values of M01 do not automatically apply across mechanisms.","assembly_status":"partial","boundary_rationale":"Selection of the marginal position directly determines the uniform price, which is directly implemented as the execution rate and payment and receipt rates for winning trades, constituting a single price-application rule; it is not merged with M01 pairwise pricing.","chain_bindings":[{"chain_id":"v141-c-R013","ownership":"primary","role":"core","rationale":"Provides the maximum break-even position and the calculation of the uniform price from marginal quotations."},{"chain_id":"v141-c-R012","ownership":"primary","role":"interface","rationale":"Explains the application of the uniform price in the execution of all winning trades."},{"chain_id":"v141-c-R014","ownership":"primary","role":"core","rationale":"Implements the uniform price as the common payment and receipt rate."}],"connections":[{"connection_id":"v142-d-CL006-L01","from_chain_id":"v141-c-R013","to_chain_id":"v141-c-R012","kind":"functional_coupling","from_refs":["v141-c-R013::phi::v141-c-R013-C001"],"to_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R012::phi::v141-c-R012-C002"],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"rationale":"The maximum break-even position provides the marginal inputs for the uniform price, which is applied to execution for participants already determined to have won; no winner-determination algorithm is added."},{"connection_id":"v142-d-CL006-L02","from_chain_id":"v141-c-R013","to_chain_id":"v141-c-R014","kind":"functional_coupling","from_refs":["v141-c-R013::phi::v141-c-R013-C001"],"to_refs":["v141-c-R014::phi::v141-c-R014-C001"],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"rationale":"The same uniform price simultaneously specifies the payment and receipt rates for winning buyers and sellers; the calculation and settlement uses are complementary, and repeated price terms are not counted as additional rules."}],"object_mappings":[{"mapping_id":"v142-d-CL006-O01","kind":"same_node","member_refs":["v141-c-R012::V::pricing.local","v141-c-R013::V::pricing.local","v141-c-R014::V::pricing.local"],"canonical_ref":"v141-c-R013::V::pricing.local","display_policy":"single_representative","evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"rationale":"All three chains reference the same M02 uniform-price function; only a representative is selected for display."},{"mapping_id":"v142-d-CL006-O02","kind":"same_quantity","member_refs":["v141-c-R012::theta::v141-c-R012-T-Bgamma","v141-c-R013::theta::param_B_gamma_P","v141-c-R014::theta::theta_B_gamma"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"rationale":"The bid price at the maximum break-even position in the same M02 auction is used for pricing, execution, and settlement, respectively; the parameter records at each stage are retained."},{"mapping_id":"v142-d-CL006-O03","kind":"same_quantity","member_refs":["v141-c-R012::theta::v141-c-R012-T-Sgamma","v141-c-R013::theta::param_S_gamma_P","v141-c-R014::theta::theta_S_gamma"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"rationale":"The asking price at the maximum break-even position in the same M02 auction is used throughout all three purposes and is not equated with identically named marginal prices in other mechanisms."},{"mapping_id":"v142-d-CL006-O04","kind":"same_quantity","member_refs":["v141-c-R012::theta::v141-c-R012-T-k","v141-c-R013::theta::param_k","v141-c-R014::theta::theta_k"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-04"],"rationale":"All three are the weight in the same M02 uniform price; this identity correspondence does not certify the parameter domain added by R014 or overwrite unspecified attributes in the other chains."}],"gaps":[{"gap_id":"v142-d-CL006-G01","category":"scope_conflict","description":"The interval specified for k in R014 comes from an interpretation of the mechanism family, whereas the cited M02 table provides only price terms; R012 and R013 do not declare the same domain, and mappings of the same quantity cannot automatically supply it.","chain_ids":["v141-c-R012","v141-c-R013","v141-c-R014"],"object_refs":["v141-c-R012::theta::v141-c-R012-T-k","v141-c-R013::theta::param_k","v141-c-R014::theta::theta_k"],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"proposal_ids":[],"required_work":"Obtain an explicit source for the M02 parameter domain, and have C clarify its applicability; retain the current records without borrowing the M01 range as an established fact."},{"gap_id":"v142-d-CL006-G02","category":"math_incomplete","description":"The ordering index set and price output in R013 are not separately declared, and the output-price symbols in R012 and R014 also lack object references; handling of the absence of a break-even position is missing. Identical marginal inputs are not yet sufficient to form an algorithm covering all auction cases.","chain_ids":["v141-c-R012","v141-c-R013","v141-c-R014"],"object_refs":["v141-c-R013::phi::v141-c-R013-C001","v141-c-R012::phi::v141-c-R012-C002","v141-c-R014::phi::v141-c-R014-C001","v141-c-R014::theta::theta_gamma"],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"proposal_ids":[],"required_work":"B/C are to complete the ordering set, boundary cases for the marginal position, and output identities and units; this cluster does not introduce bidding chains across mechanisms or add price objects."},{"gap_id":"v142-d-CL006-G03","category":"unverified_source","description":"The M02 definition and the rates in Table 1 are all unreviewed candidates; the current assembly does not certify the correctness of the sourcing of the parameter domain or price formulas.","chain_ids":["v141-c-R012","v141-c-R013","v141-c-R014"],"object_refs":[],"evidence_ids":["v141-b-g01-ev-02","v141-b-g01-ev-04"],"proposal_ids":[],"required_work":"Independently verify the original M02 text and tables, and check the indices and conditions of applicability."}]},"rule_refs":["05-double_auction::v141-c-R013","05-double_auction::v141-c-R012","05-double_auction::v141-c-R014"],"unresolved_rule_refs":[],"node_ids":["COMP-6057789601b08e93","COMP-6dbc299ae7b6e3ba","COMP-c778bd4c94b4cc95","KG31-071a827919ad4921"]});
